import math

import torch
import torch.nn.functional as F
from torch import nn


class Attention(nn.Module):
    """Multi-head self-attention over B×T×D.

    Grouped-query when kv_heads < heads; RoPE (rotate-half) or none; per-head QK-norm
    ("rms" learned, "l2" plain); chunked local attention; optional additive bias heads×T×T.
    """

    def __init__(self, dim: int, heads: int, kv_heads: int | None = None, causal: bool = False, dropout: float = 0.0,
                 bias: bool = True, o_bias: bool = True, rope: bool = False, rope_theta: float = 10000.0,
                 qk_norm: str = "none", chunk: int = 0, nope_temp: bool = False):
        super().__init__()
        self.heads = heads
        self.kv_heads = kv_heads or heads
        self.head_dim = dim // heads
        self.causal, self.dropout, self.rope, self.qk_norm = causal, dropout, rope, qk_norm
        self.chunk, self.nope_temp = chunk, nope_temp
        self.q_proj = nn.Linear(dim, dim, bias=bias)
        self.k_proj = nn.Linear(dim, self.kv_heads * self.head_dim, bias=bias)
        self.v_proj = nn.Linear(dim, self.kv_heads * self.head_dim, bias=bias)
        self.o_proj = nn.Linear(dim, dim, bias=o_bias)
        if qk_norm == "rms":
            self.q_norm = nn.RMSNorm(self.head_dim, eps=1e-6)
            self.k_norm = nn.RMSNorm(self.head_dim, eps=1e-6)
        if rope:
            inv_freq = 1.0 / (rope_theta ** (torch.arange(0, self.head_dim, 2, dtype=torch.float32) / self.head_dim))
            self.register_buffer("inv_freq", inv_freq, persistent=False)

    @staticmethod
    def _rotate(x, cos, sin):
        x1, x2 = x.chunk(2, dim=-1)
        return x * cos + torch.cat([-x2, x1], dim=-1) * sin

    def forward(self, x, bias=None):
        B, T, D = x.shape
        q = self.q_proj(x).view(B, T, self.heads, self.head_dim).transpose(1, 2)
        k = self.k_proj(x).view(B, T, self.kv_heads, self.head_dim).transpose(1, 2)
        v = self.v_proj(x).view(B, T, self.kv_heads, self.head_dim).transpose(1, 2)
        if self.qk_norm == "rms":
            q, k = self.q_norm(q), self.k_norm(k)
        if self.rope:
            angles = torch.outer(torch.arange(T, device=x.device, dtype=torch.float32), self.inv_freq)
            angles = torch.cat([angles, angles], dim=-1)
            cos, sin = angles.cos().to(q.dtype), angles.sin().to(q.dtype)
            q, k = self._rotate(q, cos, sin), self._rotate(k, cos, sin)
        if self.qk_norm == "l2":
            q = q * torch.rsqrt(q.pow(2).mean(-1, keepdim=True) + 1e-6)
            k = k * torch.rsqrt(k.pow(2).mean(-1, keepdim=True) + 1e-6)
        if self.nope_temp and not self.rope:  # Llama 4: sharpen attention far into long contexts
            pos = torch.arange(T, device=x.device, dtype=torch.float32)
            q = q * (torch.log(torch.floor((pos + 1) / 8192) + 1) * 0.1 + 1).view(1, 1, T, 1).to(q.dtype)
        if self.kv_heads != self.heads:
            k = k.repeat_interleave(self.heads // self.kv_heads, dim=1)
            v = v.repeat_interleave(self.heads // self.kv_heads, dim=1)
        mask = None
        if bias is not None or (self.chunk and T > self.chunk):
            i = torch.arange(T, device=x.device)
            allowed = torch.ones(T, T, dtype=torch.bool, device=x.device)
            if self.causal:
                allowed &= i[:, None] >= i[None, :]
            if self.chunk:
                allowed &= (i[:, None] // self.chunk) == (i[None, :] // self.chunk)
            mask = torch.zeros(T, T, dtype=q.dtype, device=x.device).masked_fill(~allowed, float("-inf"))
            if bias is not None:
                mask = mask + bias.to(q.dtype)
        y = F.scaled_dot_product_attention(q, k, v, attn_mask=mask, is_causal=self.causal and mask is None,
                                           dropout_p=self.dropout if self.training else 0.0)
        return self.o_proj(y.transpose(1, 2).reshape(B, T, D))


class MLP(nn.Module):
    """fc2(act(fc1(x)))."""

    def __init__(self, dim: int, hidden: int, out: int, act: str = "gelu", dropout: float = 0.0):
        super().__init__()
        self.fc1 = nn.Linear(dim, hidden)
        self.act = {"gelu": nn.GELU(), "relu": nn.ReLU(), "silu": nn.SiLU(), "tanh": nn.Tanh()}[act]
        self.drop = nn.Dropout(dropout)
        self.fc2 = nn.Linear(hidden, out)

    def forward(self, x):
        return self.fc2(self.drop(self.act(self.fc1(x))))


class PositionalEmbedding(nn.Module):
    """x + a learned vector per position."""

    def __init__(self, max_len: int, dim: int):
        super().__init__()
        self.weight = nn.Parameter(torch.zeros(max_len, dim))
        nn.init.normal_(self.weight, std=0.02)

    def forward(self, x):
        return x + self.weight[: x.shape[1]]


class Block(nn.Module):
    """Subgraph 'block'."""

    def __init__(self):
        super().__init__()
        self.ln1 = nn.LayerNorm(64, eps=1e-05)  # node: ln1
        self.attn = Attention(64, heads=4, causal=False, dropout=0.0, bias=True)  # node: attn
        self.ln2 = nn.LayerNorm(64, eps=1e-05)  # node: ln2
        self.mlp = MLP(64, 256, 64, act='gelu', dropout=0.0)  # node: mlp

    def forward(self, x):
        ln1 = self.ln1(x)  # node: ln1  B×T×64
        attn = self.attn(ln1)  # node: attn  B×T×64
        res1 = x + attn  # node: res1  B×T×64
        ln2 = self.ln2(res1)  # node: ln2  B×T×64
        mlp = self.mlp(ln2)  # node: mlp  B×T×64
        res2 = res1 + mlp  # node: res2  B×T×64
        return res2


class Model(nn.Module):
    """Inputs: x (B×16). Returns a dict of outputs; includes "loss" when targets are given."""

    def __init__(self):
        super().__init__()
        self.emb = nn.Embedding(16, 64)  # node: emb
        self.pos = PositionalEmbedding(64, 64)  # node: pos
        self.blocks = nn.ModuleList([Block() for _ in range(2)])  # node: blocks
        self.norm = nn.LayerNorm(64, eps=1e-05)  # node: norm
        self.head = nn.Linear(64, 16)  # node: head

    def forward(self, x, y=None, **unused):
        emb = self.emb(x)  # node: emb  B×16×64
        pos = self.pos(emb)  # node: pos  B×16×64
        blocks = pos  # node: blocks
        for block in self.blocks:  # node: blocks · 2×
            blocks = block(blocks)  # node: blocks  B×16×64
        norm = self.norm(blocks)  # node: norm  B×16×64
        head = self.head(norm)  # node: head  B×16×16
        out = {'head': head}
        if y is not None:
            loss_ = F.cross_entropy(head.flatten(0, -2).float(), y.flatten())  # node: loss
            out['loss'] = loss_
        return out
